<?php require 'config.php'; need(['pharmacist','nurse','doctor','lab','radiographer']); check();
$r=user()['role'];$mgr=in_array($r,['pharmacist','admin']);$msg=$err='';$tab=$_GET['tab']??'stock';
$q=function($sql,$a=[])use($pdo){$s=$pdo->prepare($sql);$s->execute($a);return $s->fetchAll();};
if(isset($_GET['voucher'])){$v=$q('SELECT q.*,i.name,i.unit,d.name dn,u.name rb,s.name ib FROM inv_requisitions q JOIN inv_items i ON i.id=q.item_id LEFT JOIN departments d ON d.id=q.dept_id LEFT JOIN users u ON u.id=q.requested_by LEFT JOIN users s ON s.id=q.issued_by WHERE q.id=? AND q.status=\'issued\'',[(int)$_GET['voucher']]);$v=$v[0]??die('Voucher not found.');
  echo doc_open('Store issue voucher V'.str_pad($v['id'],5,'0',STR_PAD_LEFT));echo '<table><tr><td>Item<td><b>'.e($v['name']).'</b><tr><td>Quantity issued<td><b>'.$v['issued_qty'].' '.e($v['unit']).'</b><tr><td>Issued to<td>'.e($v['dn']?:'-').' (requested by '.e($v['rb']).')<tr><td>Issued by<td>'.e($v['ib']).'<tr><td>Date<td>'.e($v['issued_at']).'<tr><td>Note<td>'.e($v['note']).'</table><div class=sig><span>Issued by</span><span>Received by</span></div><div class=np><button onclick=print()>Print</button> <a href="inventory.php?tab=req">Back</a></div>';exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$mv=function($item,$d,$type,$ref)use($pdo){$pdo->prepare('INSERT INTO inv_movements(item_id,change_qty,type,ref,by_user) VALUES(?,?,?,?,?)')->execute([$item,$d,$type,$ref,user()['id']]);};
  try{
  if(isset($_POST['request'])){$n=(int)$_POST['qty'];if($n<1)$err='Enter a quantity of 1 or more.';else{$pdo->prepare('INSERT INTO inv_requisitions(item_id,qty,requested_by,dept_id,note) VALUES(?,?,?,?,?)')->execute([(int)$_POST['item'],$n,user()['id'],(int)$_POST['dept']?:null,trim($_POST['note'])]);audit('requisition');$msg='Request sent to the store.';$tab='req';}}
  elseif($mgr&&isset($_POST['newitem'])){$pdo->prepare('INSERT INTO inv_items(name,category,unit,stock,reorder_level,location,serial) VALUES(?,?,?,?,?,?,?)')->execute([trim($_POST['newitem']),$_POST['cat'],trim($_POST['unit']),max(0,(int)$_POST['stock']),max(0,(int)$_POST['reorder']),trim($_POST['loc']),trim($_POST['serial'])]);$msg='Item added.';}
  elseif($mgr&&isset($_POST['receive'])){$n=(int)$_POST['qty'];if($n<1)$err='Enter a quantity of 1 or more.';else{$pdo->prepare('UPDATE inv_items SET stock=stock+? WHERE id=?')->execute([$n,(int)$_POST['receive']]);$mv((int)$_POST['receive'],$n,'receive',trim($_POST['ref']));audit('stock received');$msg='Stock received.';}}
  elseif($mgr&&isset($_POST['adjust'])){$it=$q('SELECT stock FROM inv_items WHERE id=?',[(int)$_POST['adjust']]);$new=max(0,(int)$_POST['count']);if($it){$d=$new-$it[0]['stock'];$pdo->prepare('UPDATE inv_items SET stock=? WHERE id=?')->execute([$new,(int)$_POST['adjust']]);$mv((int)$_POST['adjust'],$d,'adjust',trim($_POST['why'])?:'stock count');audit('stock adjusted');$msg='Stock count updated.';}}
  elseif($mgr&&isset($_POST['cond'])&&in_array($_POST['c'],['good','needs repair','out of service'])){$pdo->prepare('UPDATE inv_items SET cond=? WHERE id=?')->execute([$_POST['c'],(int)$_POST['cond']]);$msg='Condition updated.';}
  elseif($mgr&&isset($_POST['issue'])){$rq=$q("SELECT * FROM inv_requisitions WHERE id=? AND status='pending'",[(int)$_POST['issue']]);$n=(int)$_POST['qty'];
    if(!$rq||$n<1)$err='Enter a quantity to issue.';else{$pdo->beginTransaction();$u=$pdo->prepare('UPDATE inv_items SET stock=stock-? WHERE id=? AND stock>=?');$u->execute([$n,$rq[0]['item_id'],$n]);
      if(!$u->rowCount()){$pdo->rollBack();$err='Not enough stock to issue that quantity.';}
      else{$pdo->prepare("UPDATE inv_requisitions SET status='issued',issued_qty=?,issued_by=?,issued_at=NOW() WHERE id=?")->execute([$n,user()['id'],$rq[0]['id']]);$mv($rq[0]['item_id'],-$n,'issue','REQ#'.$rq[0]['id']);$pdo->commit();audit('issued requisition '.$rq[0]['id']);header('Location: inventory.php?voucher='.$rq[0]['id']);exit;}}}
  elseif($mgr&&isset($_POST['reject'])){$pdo->prepare("UPDATE inv_requisitions SET status='rejected',issued_by=? WHERE id=? AND status='pending'")->execute([user()['id'],(int)$_POST['reject']]);$msg='Request rejected.';$tab='req';}
  }catch(PDOException $x){if($pdo->inTransaction())$pdo->rollBack();$err=$x->errorInfo[1]==1062?'That item already exists.':'Could not save.';}}
head('Inventory');if($msg)echo '<p class=ok>'.e($msg).'</p>';if($err)echo '<p class=err>'.e($err).'</p>';
echo '<p><a href="inventory.php">Stock</a> | <a href="inventory.php?tab=req">Requisitions</a> | <a href="inventory.php?tab=log">Movements</a></p>';
$items=$q('SELECT * FROM inv_items ORDER BY category,name');
if($tab=='stock'){$low=array_filter($items,function($i){return $i['stock']<=$i['reorder_level'];});if($low&&$mgr)echo '<div class=card><b class=err>Low stock:</b> '.e(implode(', ',array_column($low,'name'))).'</div>';
  echo '<div class=card><table><tr><th>Item<th>Type<th>Stock<th>Location<th>Condition'.($mgr?'<th>Receive<th>Count':'').'</tr>';
  foreach($items as $i){echo '<tr><td>'.e($i['name']).($i['serial']?' <small>('.e($i['serial']).')</small>':'').'<td>'.e($i['category']).'<td>'.$i['stock'].' '.e($i['unit']).($i['stock']<=$i['reorder_level']?' <b class=err>low</b>':'').'<td>'.e($i['location']).'<td>';
    if($i['category']=='Equipment'){if($mgr){echo '<form method=post style="display:flex;gap:4px">'.field().'<input type=hidden name=cond value='.$i['id'].'><select name=c>';foreach(['good','needs repair','out of service'] as $c)echo '<option'.($c==$i['cond']?' selected':'').'>'.$c;echo '</select><button style="margin:0">Set</button></form>';}else echo e($i['cond']);}else echo '-';
    if($mgr)echo '<td><form method=post style="display:flex;gap:4px">'.field().'<input type=hidden name=receive value='.$i['id'].'><input name=qty type=number min=1 style="width:70px"><input name=ref placeholder="Delivery note" style="width:110px"><button style="margin:0">Add</button></form><td><form method=post style="display:flex;gap:4px">'.field().'<input type=hidden name=adjust value='.$i['id'].'><input name=count type=number min=0 style="width:70px" placeholder="Counted"><input name=why placeholder="Reason" style="width:90px"><button style="margin:0">Set</button></form>';}
  echo '</table></div>';
  if($mgr)echo '<div class=card><h3>Add an item</h3><form method=post class=g>'.field().'<div><input name=newitem placeholder="Item name" required></div><div><select name=cat><option>Supplies<option>Consumables<option>Equipment</select></div><div><input name=unit placeholder="Unit (box, piece)"></div><div><input name=stock type=number min=0 value=0 placeholder="Opening stock"></div><div><input name=reorder type=number min=0 value=5 placeholder="Low-stock level"></div><div><input name=loc placeholder="Location"></div><div><input name=serial placeholder="Serial no (equipment)"></div><div><button style="margin:0">Add item</button></div></form></div>';}
if($tab=='req'){echo '<div class=card><h3>Request items from the store</h3><form method=post class=g>'.field().'<input type=hidden name=request value=1><div><select name=item>';foreach($items as $i)echo '<option value='.$i['id'].'>'.e($i['name']).' (in store: '.$i['stock'].')';echo '</select></div><div><input name=qty type=number min=1 placeholder="Quantity" required></div><div><select name=dept><option value=0>For which service point?';foreach(depts() as $d)echo '<option value='.$d['id'].'>'.e($d['name']);echo '</select></div><div><input name=note placeholder="Note"></div><div><button style="margin:0">Send request</button></div></form></div>';
  echo '<div class=card><table><tr><th>#<th>Item<th>Qty<th>For<th>By<th>Status<th></tr>';foreach($q('SELECT q.*,i.name,i.unit,d.name dn,u.name rb FROM inv_requisitions q JOIN inv_items i ON i.id=q.item_id LEFT JOIN departments d ON d.id=q.dept_id LEFT JOIN users u ON u.id=q.requested_by ORDER BY q.status=\'pending\' DESC,q.id DESC LIMIT 60') as $x){
    echo '<tr><td>'.$x['id'].'<td>'.e($x['name']).'<td>'.$x['qty'].' '.e($x['unit']).'<td>'.e($x['dn']).'<td>'.e($x['rb']).'<td>'.e($x['status']).'<td>';
    if($x['status']=='pending'&&$mgr)echo '<form method=post style="display:flex;gap:4px">'.field().'<input name=qty type=number min=1 value='.$x['qty'].' style="width:70px"><button name=issue value='.$x['id'].' style="margin:0">Issue</button><button name=reject value='.$x['id'].' style="margin:0;background:#a23b2a">Reject</button></form>';
    elseif($x['status']=='issued')echo '<a target=_blank href="inventory.php?voucher='.$x['id'].'">Voucher</a>';}
  echo '</table></div>';}
if($tab=='log'){echo '<div class=card><table><tr><th>Time<th>Item<th>Change<th>Type<th>Reference<th>By</tr>';foreach($q('SELECT m.*,i.name,u.name un FROM inv_movements m JOIN inv_items i ON i.id=m.item_id LEFT JOIN users u ON u.id=m.by_user ORDER BY m.id DESC LIMIT 80') as $m)echo '<tr><td>'.substr($m['created_at'],0,16).'<td>'.e($m['name']).'<td>'.($m['change_qty']>0?'+':'').$m['change_qty'].'<td>'.e($m['type']).'<td>'.e($m['ref']).'<td>'.e($m['un']);echo '</table></div>';}
foot();
